/*selectMasterMdCmBuyerCatalogAlterPopList*/ SELECT (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.AGENT) AS AGENT_NAME, --[00] A.SELLER_ITEM_NO, --[01] A.UNIT_PRICE, --[02] A.LIST_PRICE, --[03] A.MAKER_NAME, --[04] A.MAKER_PART_NO, --[05] (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M001' AND CODE = A.ORIGIN_CODE) AS ORIGIN_TEXT, --[06] (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.ORIGIN_AGENT) AS ORIGIN_AGENT_NAME, --[07] (SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M034' AND CODE = A.PROCESS_TYPE) AS PROCESS_TEXT, --[08] A.CHANGE_DATE, --[09] A.LAST_PO_PRICE, --[10] A.LAST_PO_QTY, --[11] A.LAST_PO_DATE, --[12] DECODE (A.BELOW_COMORG_CODE, 'ABOVE', '공통/나머지', (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = A.BELOW_COMORG_CODE)) AS BELOW_TEXT, --[13] A.BUYER, --[14] A.AGENT AS AGENT, --[15] A.ORIGIN_CODE, --[16] A.ORIGIN_AGENT AS ORIGIN_AGENT, --[17] A.PROCESS_TYPE, --[18] A.BELOW_COMORG_CODE, --[19] A.CONTRACT_NO, --[20] A.CONTRACT_SEQ, --[21] A.STATUS, --[22] DECODE (A.STATUS, 'D', '삭제', '사용') ||' / '|| DECODE ( (SELECT PRODUCT_CLOSE_FLAG FROM ICOMBYIT WHERE BUYER = A.BUYER
AND BUYER_ITEM_NO = A.BUYER_ITEM_NO),'N','승인','Y','미승인','T','I/F품목','A','일회용_미발주','C','일회용_기발주','B','BLOCKED' ) AS STATUS_TEXT, --[24]
AND BUYER_ITEM_NO = A.BUYER_ITEM_NO),'N','승인','Y','미승인','T','I/F품목','A','일회용_미발주','C','신규요청품목') AS STATUS_TEXT, --[24]
AND BUYER_ITEM_NO = A.BUYER_ITEM_NO),'N','승인','Y','미승인','T','I/F품목') AS STATUS_TEXT, --[24]
A.PROCESS_TYPE, --[25] (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'M102' AND CODE = A.ITEM_GROUP) AS ITEM_GROUP_TEXT, --[26] A.ITEM_GROUP, --[27] A.MAKER_CODE, --[28] A.IMPORT_FLAG AS IMPORT_FLAG, --[30] A.UNIT_PRICE AS BEF_UNIT_PRICE, A.LIST_PRICE AS BEF_LIST_PRICE, A.ORIGIN_CODE AS BEF_ORIGIN_CODE, A.MAKER_CODE AS BEF_MAKER_CODE, A.MAKER_NAME AS BEF_MAKER_NAME, A.AGENT AS BEF_AGENT, A.ACCOUNT_TYPE, NVL((SELECT TEXT2 FROM ICOMCOD2 WHERE TYPE = 'Z014' AND COMPANY_CODE = #{st_buyer_code} AND CODE = A.ACCOUNT_TYPE),(SELECT TEXT2 FROM ICOMCOD1 WHERE TYPE = 'M014' AND CODE = A.ACCOUNT_TYPE)) AS ACCOUNT_TEXT, A.ITEM_MAKE_TYPE AS BEF_ITEM_MAKE_TYPE, A.ITEM_MAKE_TYPE, A.DELIVERY_LT AS BEF_DELIVERY_LT, A.DELIVERY_LT, A.MIN_ORDER_QTY AS BEF_MIN_ORDER_QTY, A.MIN_ORDER_QTY, A.PUR_UNIT_QTY AS BEF_PUR_UNIT_QTY, A.PUR_UNIT_QTY, A.SELLER_AREA AS BEF_SELLER_AREA, A.SELLER_AREA, DECODE(A.SELLER_AREA,'','4','5') AS SELLER_AREA_IMG, F_GET_LOGISTICS_FEE_INFO(A.BELOW_COMORG_CODE,A.BUYER_ITEM_NO, A.PROCESS_TYPE, A.AGENT, 0,'02', A.ORIGIN_AGENT) AS LOGISTICS_RATE, F_GET_LOGISTICS_FEE_INFO(A.BELOW_COMORG_CODE,A.BUYER_ITEM_NO, A.PROCESS_TYPE, A.AGENT, 0,'03', A.ORIGIN_AGENT) AS LOGIS_RATE_STATUS, (SELECT DECODE(COUNT(EXP_CODE),0,'4','5') FROM KEP_CURRENCY_DT DT WHERE DT.BUYER = A.BUYER AND DT.BUYER_ITEM_NO = A.BUYER_ITEM_NO AND DT.CONTRACT_NO = A.CONTRACT_NO AND DT.CONTRACT_SEQ = A.CONTRACT_SEQ) AS CUNRRENCY_IMG , A.BUYER_ITEM_NO, A.DEL_STATUS_CODE, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'CC01' AND CODE = A.DEL_STATUS_CODE) AS DEL_STATUS_CODE_TEXT, A.TO_DATE AS RE_TO_DATE, A.TO_DATE AS CH_TO_DATE, (SELECT DECODE(COUNT(ADD_USER_ID),0,'4','5') FROM ICOMCQEP CQEP WHERE CQEP.BUYER = A.BUYER AND CQEP.BUYER_ITEM_NO = A.BUYER_ITEM_NO AND CQEP.CONTRACT_NO = A.CONTRACT_NO AND CQEP.CONTRACT_SEQ = A.CONTRACT_SEQ) AS UNIT_PRICE_HISTORY_IMG, A.SELL_CLOSE_DATE AS RE_SELL_CLOSE_DATE, A.SELL_CLOSE_DATE AS CH_SELL_CLOSE_DATE, A.BUY_CLOSE_DATE AS RE_BUY_CLOSE_DATE, A.BUY_CLOSE_DATE AS CH_BUY_CLOSE_DATE FROM ICOMCQDT A WHERE A.BUYER = #{st_catalog_com_code} AND A.BUYER_ITEM_NO = #{st_buyer_item_no}
AND A.BELOW_COMORG_CODE = #{st_buyer_code}
ORDER BY A.AGENT , A.CONTRACT_NO,A.CONTRACT_SEQ

