UPDATE ICOMCQDT /*deleteMasterMdCmBuyerCatalogAlterPop1*/
   SET CHANGE_DATE = TO_CHAR (SYSDATE, 'YYYYMMDD'),
       CHANGE_TIME = TO_CHAR (SYSDATE, 'HH24MISS'),
       STATUS = 'D',
       DEL_STATUS_CODE = #{DEL_STATUS_CODE}
 WHERE     BUYER = #{st_catalog_com_code}
       AND BUYER_ITEM_NO = #{st_buyer_item_no}
       AND CONTRACT_NO = #{CONTRACT_NO}
       AND CONTRACT_SEQ = #{CONTRACT_SEQ}


