    AND CONTRACT_NO = #{CONTRACT_NO}
    AND CONTRACT_SEQ = #{CONTRACT_SEQ}

UPDATE ICOMBYIT /*confirmMasterMdCmBuyerCatalogAlterPop2*/ SET STATUS = 'R', PRODUCT_CLOSE_FLAG = #{st_product_flag}, CHANGE_DATE = TO_CHAR (SYSDATE, 'YYYYMMDD'), CHANGE_USER_ID = #{st_user_id}, CHANGE_USER_TEL = #{st_user_tel}, CHANGE_USER_NAME = #{st_user_name}, CHANGE_USER_DEPT = #{st_user_dept},
CLOSE_STATUS_CODE = #{CLOSE_STATUS_CODE}
