UPDATE ICOMCQEP /*saveMasterMdCmBuyerCatalogAlterPop2*/
   SET CHANGE_DATE = TO_CHAR (SYSDATE, 'YYYYMMDD'),
       CHANGE_TIME = TO_CHAR (SYSDATE, 'HH24MISS'),
       TO_DATE = TO_CHAR (SYSDATE, 'YYYYMMDD')
 WHERE     BUYER = #{st_catalog_com_code}
       AND CONTRACT_NO = #{CONTRACT_NO}
       AND CONTRACT_SEQ = #{CONTRACT_SEQ}
       AND BUYER_ITEM_NO = #{st_buyer_item_no}
       AND TO_CHAR (SYSDATE, 'YYYYMMDD') BETWEEN FROM_DATE AND TO_DATE


		  UPDATE ICOMPRDT A
           SET  LIST_PRICE    = ( SELECT C.CH_LIST_PRICE  FROM KEPMGPDT C WHERE C.BUYER = A.BUYER
           							AND C.QUOTATION_NO = A.PR_NO
           							AND C.QUOTATION_SEQ = A.PR_SEQ
           							AND A.BUYER = #{KEY_2}
           							AND PM_NO = #{KEY_1}
           							)
          WHERE (A.BUYER, A.PR_NO , A.PR_SEQ) IN (
			           SELECT B.BUYER, B.QUOTATION_NO ,B.QUOTATION_SEQ FROM KEPMGPDT B
			           WHERE  BUYER = #{KEY_2}
			           AND PM_NO = #{KEY_1}
			           )


				UPDATE ICOMBYIT A SET  /*insertMasterMdCmBuyerCatalogAlterPop3*/
                                   PURCHASER_ID = #{st_user_id},   
                                   PURCHASER_NAME = (SELECT L.USER_NAME_LOC FROM ICOMLUSR L WHERE L.USER_ID = #{st_user_id}),   
                                   AGENT_CNT = TO_NUMBER((SELECT COUNT(*) FROM ICOMCQDT   
                                                          WHERE BUYER = #{st_catalog_com_code}  
                                                            AND BUYER_ITEM_NO = #{st_buyer_item_no}  
                                                            AND STATUS <> 'D'))  
              WHERE A.BUYER = #{st_catalog_com_code}  
                AND A.BUYER_ITEM_NO = #{st_buyer_item_no}

