UPDATE ICOMCQEP  /*updateCaApprovalIBelowCOMCQEP*/
   SET CHANGE_DATE = TO_CHAR (SYSDATE, 'YYYYMMDD'),
       CHANGE_TIME = TO_CHAR (SYSDATE, 'HH24MISS'),
       TO_DATE = TO_CHAR (SYSDATE, 'YYYYMMDD')
 WHERE (BUYER, CONTRACT_NO, CONTRACT_SEQ, BUYER_ITEM_NO) IN
          (SELECT BUYER,
                  CONTRACT_NO,
                  CONTRACT_SEQ,
                  BUYER_ITEM_NO
             FROM ICOMCQDT
            WHERE     BUYER = #{st_catalog_com_code}
                  AND BUYER_ITEM_NO = #{st_buyer_item_no}
                  AND AGENT = #{AGENT}
                  AND PROCESS_TYPE = #{PROCESS_TYPE}
                  AND BELOW_COMORG_CODE = #{st_below_comorg_code}
                  AND STATUS <> 'D')


