/*updateMdCmrctRequest*/
UPDATE KEP_RCDT 
   SET RC_TYPE = 'W'
   , CHANGE_DATE = SYSDATE
   , CHANGE_USER_ID = #{USER_ID}
 WHERE (RC_NO,RC_SEQ,REVISION) IN (
 	SELECT A.QUOTATION_NO, A.QUOTATION_SEQ, A.REVISION 
 	FROM KEPMGPDT A
	WHERE BUYER = #{KEY_2}
	AND PM_NO = #{KEY_1}
 )
 AND RC_TYPE= 'S'


